// 快排：分区在原数组上，递归处理两半
void quickSort(int a[], int lo, int hi) {
    if (lo < hi) {
        int p = partition(a, lo, hi);   // 原地分区
        quickSort(a, lo, p - 1);
        quickSort(a, p + 1, hi);
    }
}

// 归并：先递归拆分，再合并到辅助数组
void mergeSort(int a[], int lo, int hi) {
    if (hi - lo < 2) return;
    int mid = (lo + hi) / 2;
    mergeSort(a, lo, mid);              // 拆左
    mergeSort(a, mid, hi);              // 拆右
    merge(a, lo, mid, hi);              // 合并（需 O(n) 辅助空间）
}
```

